import{c as e,Q as r,j as s,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"HarnessX / DecentMem 落地可行性評估 — 值得做嗎？","description":"","frontmatter":{"title":"HarnessX / DecentMem 落地可行性評估 — 值得做嗎？","date":"2026-06-20T00:00:00.000Z","status":"eval complete","branch":"claude/anthropic-claude-code-expertise-5myrpg","method":"讀一手 MD + PDF 歸檔 → 主對話 grep 接地轉移條件 → fable-pilot 審閱","papers":["HarnessX (arXiv 2606.14249) — Critical 自評","DecentMem (arXiv 2605.22721) — High 自評"],"type":"feasibility-eval + verdict","verdict_policy":"不採信論文 headline 數字為 workspace-applicable；只認「轉移條件成立 + 真實失敗模式 + Rule-of-3」三關全過"},"headers":[],"relativePath":"research/reports/2026-06-20-harnessx-decentmem-feasibility-eval.md","filePath":"research/reports/2026-06-20-harnessx-decentmem-feasibility-eval.md","lastUpdated":1785909234000}'),n={name:"research/reports/2026-06-20-harnessx-decentmem-feasibility-eval.md"};function o(d,t,i,c,l,g){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="harnessx-decentmem-落地可行性評估" tabindex="-1">HarnessX / DecentMem 落地可行性評估 <a class="header-anchor" href="#harnessx-decentmem-落地可行性評估" aria-label="Permalink to &quot;HarnessX / DecentMem 落地可行性評估&quot;">​</a></h1><blockquote><p><strong>核心問題</strong>：這兩篇論文的 idea <strong>在本 workspace 落地</strong>是否值得做？（非「論文好不好」——論文都是 V 接地的優質工作。） <strong>判準（三關全過才 worth）</strong>：① 轉移條件成立（論文前提在 workspace 為真）；② 解決 workspace <strong>實存</strong>失敗模式（非假想）；③ Rule-of-3 / 不過度工程。 <strong>anti-hack 鐵律</strong>：論文的 +14.5% / +23.8% / −49% 是<strong>其 benchmark × 其架構</strong>的結果，<strong>不等於</strong> workspace 增益；採信前須驗轉移條件。</p></blockquote><hr><h2 id="_0-verdict-tl-dr" tabindex="-1">0. Verdict TL;DR <a class="header-anchor" href="#_0-verdict-tl-dr" aria-label="Permalink to &quot;0. Verdict TL;DR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>論文</th><th>落地 Verdict</th><th>一句話理由</th></tr></thead><tbody><tr><td><strong>HarnessX — AEGIS 演化引擎</strong></td><td>❌ <strong>DON&#39;T BUILD</strong></td><td>缺前置基建（自動 trace pipeline）+ codebase 未釋出 + 多 agent 演化成本高；ROI 為負</td></tr><tr><td><strong>HarnessX — 九維分類法 checklist</strong></td><td>✅ <strong>DO（小）</strong></td><td>真實缺口（harness-meta 無此 checklist）+ 低成本（~15 行）+ 操作化「harness 完整性」</td></tr><tr><td><strong>HarnessX — seesaw = unverified_success 背書</strong></td><td>✅ <strong>DO（≈0 成本）</strong></td><td>一行 citation，把既有閘門接上學術理論背書</td></tr><tr><td><strong>DecentMem — per-agent 雙池記憶</strong></td><td>❌ <strong>DROP</strong>（非 P2，連觀察都不必升級為實作路徑）</td><td>前提<strong>結構性不成立</strong>：workspace 無「跨 agent 共享活記憶池」可崩潰；bandit 數學不遷移</td></tr></tbody></table><p><strong>淨可執行殘留 = 1 個小項</strong>（HarnessX 九維 checklist + seesaw citation，可合併一次 ≤20 行 edit）。其餘皆 DROP/保留為 archive reference。</p><hr><h2 id="_1-harnessx-—-分層評估" tabindex="-1">1. HarnessX — 分層評估 <a class="header-anchor" href="#_1-harnessx-—-分層評估" aria-label="Permalink to &quot;1. HarnessX — 分層評估&quot;">​</a></h2><h3 id="_1-1-aegis-演化引擎-—-don-t-build-轉移條件失敗" tabindex="-1">1.1 AEGIS 演化引擎 — DON&#39;T BUILD（轉移條件失敗） <a class="header-anchor" href="#_1-1-aegis-演化引擎-—-don-t-build-轉移條件失敗" aria-label="Permalink to &quot;1.1 AEGIS 演化引擎 — DON&#39;T BUILD（轉移條件失敗）&quot;">​</a></h3><p>AEGIS 四階段（Digester→Planner→Evolver→Critic+Gate）需要的前置基建 vs workspace 實況（grep 接地）：</p><table tabindex="0"><thead><tr><th>AEGIS 前置</th><th>workspace 實況</th><th>成立?</th></tr></thead><tbody><tr><td>自動 trace pipeline（每迭代 ~10M tokens raw traces → Digester）</td><td>evals/ 為<strong>手動/週期</strong> baseline+runs，<strong>無連續 trace 餵入</strong></td><td>❌</td></tr><tr><td>確定性 benchmark gate（seesaw：候選不得 regress 任何通過任務）</td><td><code>measure.sh --gate</code>(exit 1) + healthcheck <strong>存在但範圍窄</strong>（byte cap/header/anchor，非任務 benchmark suite）</td><td>⚠️ 部分</td></tr><tr><td>多 agent 演化 compute 預算</td><td>workspace 是個人 harness，多 agent 演化成本（論文自陳「cost-performance tradeoff 顯著」）不合比例</td><td>❌</td></tr><tr><td>可直接用的實作</td><td>codebase「未來釋出」(§7)</td><td>❌</td></tr></tbody></table><p>→ <strong>4 條前置 3 缺 1 部分</strong>。AEGIS 的 +14.5% 來自「自動 trace + benchmark gate + 多 agent compute」三者齊備；workspace 三缺，<strong>移植 = 從零建一套 eval 基建</strong>，遠超任何 idea 的價值。<strong>ROI 為負，DON&#39;T BUILD。</strong></p><h3 id="_1-2-九維分類法-d1–d9-—-do-小-真實缺口" tabindex="-1">1.2 九維分類法（D1–D9）— DO（小，真實缺口） <a class="header-anchor" href="#_1-2-九維分類法-d1–d9-—-do-小-真實缺口" aria-label="Permalink to &quot;1.2 九維分類法（D1–D9）— DO（小，真實缺口）&quot;">​</a></h3><p>D1 模型選擇 / D2 上下文組裝 / D3 記憶管理 / D4 工具生態 / D5 執行環境 / D6 評估獎勵 / D7 控制安全 / D8 可觀測性 / D9 訓練橋接。</p><ul><li><strong>真實缺口</strong>：grep <code>harness-meta/</code> → <strong>無任何九維/完整性 checklist</strong>。workspace 的 harness 稽核（K×M、HMF）有過程但<strong>無「九維是否都覆蓋」的完整性對照表</strong>。</li><li><strong>價值</strong>：D1–D9 是「harness 設計有沒有漏掉一整類」的機械 checklist，正交補強既有稽核（對照本 session 稍早 TIER B 的 ETCLOVG 7 類失敗分類——兩者一個是<strong>設計維度</strong>一個是<strong>失敗分類</strong>，互補不重複）。</li><li><strong>成本</strong>：~15 行掛 <code>harness-meta</code> GOTCHAS/ref，<strong>不佔 auto-load byte</strong>。</li><li><strong>Rule-of-3</strong>：harness 稽核是高頻活動（harness-meta 整個 skill 存在），checklist 有多次複用點 → 過關。</li><li><strong>Verdict：DO</strong>（小、低風險、真實缺口）。</li></ul><h3 id="_1-3-seesaw-constraint-—-do-≈0-成本-citation" tabindex="-1">1.3 seesaw constraint — DO（≈0 成本 citation） <a class="header-anchor" href="#_1-3-seesaw-constraint-—-do-≈0-成本-citation" aria-label="Permalink to &quot;1.3 seesaw constraint — DO（≈0 成本 citation）&quot;">​</a></h3><p>seesaw（候選不得 regress 任何先前通過任務）= core.md「能通過任何實作的測試 = 沒有測試」+ <code>unverified_success</code> 閘門的<strong>數學形式化</strong>。一行 citation 把既有閘門接上學術背書，強化「為何這條閘門非裝飾」的說服力。<strong>DO</strong>。</p><hr><h2 id="_2-decentmem-—-drop-前提結構性不成立" tabindex="-1">2. DecentMem — DROP（前提結構性不成立） <a class="header-anchor" href="#_2-decentmem-—-drop-前提結構性不成立" aria-label="Permalink to &quot;2. DecentMem — DROP（前提結構性不成立）&quot;">​</a></h2><p>DecentMem 的增益（+23.8% acc / −49% token）來自解決「<strong>集中式共享記憶 → agent 多樣性崩潰</strong>」。關鍵問題：<strong>workspace 有這個問題嗎？</strong></p><h3 id="_2-1-轉移條件逐項證偽-grep-接地" tabindex="-1">2.1 轉移條件逐項證偽（grep 接地） <a class="header-anchor" href="#_2-1-轉移條件逐項證偽-grep-接地" aria-label="Permalink to &quot;2.1 轉移條件逐項證偽（grep 接地）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>DecentMem 前提</th><th>workspace 實況</th><th>成立?</th></tr></thead><tbody><tr><td>多 agent <strong>共享</strong>集中式記憶池</td><td>CLAUDE.md:3「<strong>Sub-agents 不繼承本檔</strong>」；subagent-strategy:22「MEMORY session 開始注入（非實時）」；child「只含結果」</td><td>❌ <strong>無共享活記憶池</strong></td></tr><tr><td>agent <strong>持續自我演化</strong>（重複 trials 同 task）</td><td>workspace subagent = <strong>單次 fan-out、異質任務、無狀態 worker</strong></td><td>❌</td></tr><tr><td>「多樣性崩潰」病徵存在</td><td>無病徵證據；subagent 本就獨立 context、不互通</td><td>❌ 無證據支持</td></tr><tr><td>bandit reward 模型（stationary、重複）</td><td>跨 session 人工 MEMORY = 人類決策日誌，非 stationary reward 環境</td><td>❌</td></tr></tbody></table><p>→ <strong>4 條前提全不成立</strong>。<code>MEMORY.md</code>（616 行）是<strong>主對話/人類的跨 session 決策日誌</strong>，不是「多 agent 共享的活記憶池」——兩者只是都叫「memory」，本質完全不同。DecentMem 解的是 persistent self-evolving MAS 的問題，<strong>workspace 的 subagent 根本不是那種架構</strong>。</p><h3 id="_2-2-結論" tabindex="-1">2.2 結論 <a class="header-anchor" href="#_2-2-結論" aria-label="Permalink to &quot;2.2 結論&quot;">​</a></h3><p><strong>DROP（不升為實作路徑）</strong>。O(log T) regret 的理論最優性是針對 bandit 環境，與 workspace 場景無關。<strong>保留為 archive reference</strong>（已歸檔），但 EVOLUTION-QUEUE 的 observe 條目應誠實標註「前提證偽，不轉 apply」。無證據顯示 workspace 有多樣性崩潰；為不存在的問題重構 MEMORY.md = 過度工程典型。</p><hr><h2 id="_3-呼應週報-日報研究成果-研究脈絡定位" tabindex="-1">3. 呼應週報 / 日報研究成果（研究脈絡定位） <a class="header-anchor" href="#_3-呼應週報-日報研究成果-研究脈絡定位" aria-label="Permalink to &quot;3. 呼應週報 / 日報研究成果（研究脈絡定位）&quot;">​</a></h2><blockquote><p>這兩篇不是孤立論文——把它們放回本 session 的週報（2026-06-18）與日報（06-15~06-20）研究弧裡，verdict 會更穩固。</p></blockquote><h3 id="_3-1-harnessx-是「harness-模型」研究弧的第三幕" tabindex="-1">3.1 HarnessX 是「harness &gt; 模型」研究弧的<strong>第三幕</strong> <a class="header-anchor" href="#_3-1-harnessx-是「harness-模型」研究弧的第三幕" aria-label="Permalink to &quot;3.1 HarnessX 是「harness &gt; 模型」研究弧的**第三幕**&quot;">​</a></h3><p>本 session 週報深度報告已建立三證匯流，HarnessX 正好接在後面，形成完整論述弧：</p><table tabindex="0"><thead><tr><th>幕</th><th>來源</th><th>命題</th><th>性質</th></tr></thead><tbody><tr><td>一：harness <strong>已是主體</strong></td><td>CC 逆向工程 98.4% 確定性（VILA-Lab 2604.14228）</td><td>「AI 不需更聰明，需被管理」</td><td>觀察</td></tr><tr><td>二：harness 差異<strong>可量化</strong></td><td>Harness-Bench 2605.27922 同模型跨 harness <strong>23.8pt</strong></td><td>「報告 capability 須在 model–harness 層級」</td><td>量測</td></tr><tr><td>三：harness <strong>可自動演化</strong></td><td><strong>HarnessX 2606.14249 / AEGIS +14.5%</strong></td><td>「harness = composable/evolvable first-class object」</td><td>工程框架</td></tr></tbody></table><p><strong>關鍵定位</strong>：workspace 已經站在「第一幕」的勝局——它本身就是一個與 CC 同構的<strong>手工但高品質 harness</strong>（週報 §6.1 已 grep 接地）。HarnessX 的增量價值集中在「<strong>第三幕的自動化演化</strong>」，而那正是 workspace 缺基建的部分（§1.1）。 → 所以 workspace 該擷取的是 HarnessX 的<strong>理論層（九維分類 + seesaw 形式化，第一/二幕的結晶）</strong>，<strong>不是</strong>演化機器 AEGIS（第三幕的重型實作）。<strong>這個取捨完全由研究弧的位置決定，非主觀。</strong></p><h3 id="_3-2-decentmem-與日報「borrowed-intelligence」主軸正交——反而坐實-drop" tabindex="-1">3.2 DecentMem 與日報「borrowed intelligence」主軸<strong>正交</strong>——反而坐實 DROP <a class="header-anchor" href="#_3-2-decentmem-與日報「borrowed-intelligence」主軸正交——反而坐實-drop" aria-label="Permalink to &quot;3.2 DecentMem 與日報「borrowed intelligence」主軸**正交**——反而坐實 DROP&quot;">​</a></h3><p>日報 06-19 三主題（treat-intelligence-borrowed / code-as-cache / code-economics-flip）收斂到一句話：<strong>模型是借來的、隨時會因政策（Fable ban）或成本（GLM-5.2 1/6 價）消失；持久護城河 = 工程紀律（spec 品質 / behavioral test / observability）</strong>（Charity Majors「AI 對工程紀律的要求不降反升」）。</p><ul><li>DecentMem 主張「<strong>memory 架構</strong>是 MAS 自我演化的護城河」——但日報指認的護城河是 <strong>spec / gate / observability</strong>，<strong>不是</strong> per-agent memory 機制。兩者層級不同。</li><li>更關鍵：日報的護城河全部是「<strong>便宜、確定性、跨模型持久</strong>」的東西（spec 是文字、gate 是 bash、observability 是 log）。DecentMem 的雙池 + LLM-as-judge reweight 是「<strong>昂貴、隨機、綁特定 MAS 架構</strong>」的機制——<strong>與日報訊息方向相反</strong>。</li><li>→ 日報研究成果<strong>不支持</strong>引入 DecentMem，反而強化「為不存在的多樣性崩潰問題重構 MEMORY = 違反 borrowed-intelligence 紀律」。</li></ul><h3 id="_3-3-整體呼應-研究成果指向「操作化-自動化」" tabindex="-1">3.3 整體呼應：研究成果指向「操作化 &gt; 自動化」 <a class="header-anchor" href="#_3-3-整體呼應-研究成果指向「操作化-自動化」" aria-label="Permalink to &quot;3.3 整體呼應：研究成果指向「操作化 &gt; 自動化」&quot;">​</a></h3><p>週報 + 日報的合成訊息是 verdict 的最強背書：</p><blockquote><p><strong>持久護城河 = 便宜的確定性紀律（checklist / gate / spec / observability），不是昂貴的自動化魔法。</strong></p></blockquote><p>這條訊息：</p><ul><li><strong>支持</strong> HarnessX 的「harness first-class」哲學 + 取其 cheap 結晶（九維 checklist / seesaw citation）；</li><li><strong>反對</strong> 投入建 AEGIS（把 harness 變成另一個需維護的重型隨機系統，違反 Charity Majors 紀律）；</li><li><strong>反對</strong> DecentMem 重構（昂貴、綁架構、解假想問題）。</li></ul><p>§0 的 verdict（取 cheap 結晶、DROP 重型引擎）<strong>主由 §1–2 轉移條件獨立成立，並獲週報/日報研究成果佐證</strong>——非保守，是證據與脈絡雙重收斂。</p><hr><h2 id="_4-與本-session-既有帳本的一致性" tabindex="-1">4. 與本 session 既有帳本的一致性 <a class="header-anchor" href="#_4-與本-session-既有帳本的一致性" aria-label="Permalink to &quot;4. 與本 session 既有帳本的一致性&quot;">​</a></h2><ul><li>本 session A3 曾把 HarnessX/DecentMem 加為 EVOLUTION-QUEUE <strong>觀察候選</strong>（標「前提不遷移、須重評」）。<strong>本報告即該重評</strong>： <ul><li>HarnessX → 觀察候選降為「只取九維 checklist 小項，AEGIS 引擎 DROP」</li><li>DecentMem → 觀察候選<strong>證偽</strong>，建議標 closed（archive-only），不再佔 queue 注意力</li></ul></li><li>與上份週報 §6 一致：harness 投資的正確方向是<strong>操作化既有閘門</strong>（checklist/citation），非引入需大基建的自動演化引擎。</li></ul><hr><h2 id="_5-建議動作-若採納" tabindex="-1">5. 建議動作（若採納） <a class="header-anchor" href="#_5-建議動作-若採納" aria-label="Permalink to &quot;5. 建議動作（若採納）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>動作</th><th>目標檔</th><th>規模</th><th>處置</th></tr></thead><tbody><tr><td>九維 D1–D9 設計完整性 checklist + seesaw citation</td><td><code>harness-meta</code> GOTCHAS/ref（非 auto-load）</td><td>≤20 行</td><td>可做（待你確認）</td></tr><tr><td>EVOLUTION-QUEUE：DecentMem observe → closed（前提證偽）；HarnessX observe → 縮為 checklist 小項</td><td><code>research/EVOLUTION-QUEUE.md</code></td><td>≤6 行</td><td>可做（誠實化 queue）</td></tr><tr><td>AEGIS 引擎 / MEMORY 雙池重構</td><td>—</td><td>大</td><td><strong>DROP</strong></td></tr></tbody></table><blockquote><p>本報告為 report-only；上述動作需你確認後才執行（<code>.claude/</code> 與 queue 變更）。</p></blockquote><hr><p><em>方法：讀一手 MD + PDF 歸檔（HarnessX 43pp / DecentMem 27pp）→ 主對話 grep 接地轉移條件（CLAUDE.md:3 / subagent-strategy:22 / measure.sh / harness-meta）→ fable-pilot 審閱。不採信論文 headline 為 workspace 增益。</em></p>',50)])])}const b=e(n,[["render",o]]);export{p as __pageData,b as default};
